export interface Ruleset {
  id: string;
  creator_user_id: string | null;
  name: string;
  description: string | null;
  version: string | null;

  attributes_config: {
    primary: string[];
    derived: string[];
  };
  skills_config: Array<{
    name: string;
    ability: string;
  }>;
  classes_config: Array<{
    name: string;
    hit_die: string;
  }>;
  races_config: Array<{
    name: string;
    speed: number;
    size: string;
  }>;
  combat_rules: Record<string, unknown>;
  dice_rules: Record<string, unknown>;
  level_progression: Record<string, unknown>;

  is_official: boolean;
  is_public: boolean;
  is_marketplace_item: boolean;
  downloads_count: number;
  rating: number | null;

  created_at: string;
  updated_at: string;
}

export interface CreateRulesetDTO {
  name: string;
  description?: string;
  version?: string;
  attributes_config: Ruleset['attributes_config'];
  skills_config?: Ruleset['skills_config'];
  classes_config?: Ruleset['classes_config'];
  races_config?: Ruleset['races_config'];
  combat_rules?: Record<string, unknown>;
  dice_rules?: Record<string, unknown>;
  is_public?: boolean;
}

export interface UpdateRulesetDTO extends Partial<CreateRulesetDTO> {
  id: string;
}

enclosingOperation.text:
async getAll(): Promise<Ruleset[]> {
    const { data, error } = await supabase
      .from('rulesets')
      .select('*')
      .order('is_official', { ascending: false })
      .order('name');

    if (error) throw error;
    return data || [];
  }

async getOfficial(): Promise<Ruleset[]> {
    const { data, error } = await supabase
      .from('rulesets')
      .select('*')
      .eq('is_official', true)
      .order('name');

    if (error) throw error;
    return data || [];
  }

async getById(id: string): Promise<Ruleset | null> {
    const { data, error } = await supabase.from('rulesets').select('*').eq('id', id).single();

    if (error) throw error;
    return data;
  }

async create(dto: CreateRulesetDTO): Promise<Ruleset> {
    const { data, error } = await supabase
      .from('rulesets')
      .insert({
        ...dto,
        is_official: false,
        is_marketplace_item: false,
      })
      .select()
      .single();

    if (error) throw error;
    return data;
  }

async update(dto: UpdateRulesetDTO): Promise<Ruleset> {
    const { id, ...updates } = dto;
    const { data, error } = await supabase
      .from('rulesets')
      .update({
        ...updates,
        updated_at: new Date().toISOString(),
      })
      .eq('id', id)
      .select()
      .single();

    if (error) throw error;
    return data;
  }

async delete(id: string): Promise<void> {
    const { error } = await supabase.from('rulesets').delete().eq('id', id);

    if (error) throw error;
  }

